<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue'
import AppIcon from '../components/AppIcon.vue'
import { angleDegrees, distanceMm } from './model'
const src=ref(''),name=ref(''),width=ref(1),height=ref(1),error=ref(''),loading=ref(false),sample=ref(false),expertVisible=ref(false)
const tool=ref<'length'|'angle'>('length'),points=ref<[number,number][]>([]),calibration=ref<number|string>('')
const experts=ref<{symbol:string;title:string;value:{x:number;y:number}}[]>([])
let generation=0,objectUrl=''
const referenceUrl=`${import.meta.env.BASE_URL}data/dental/reference-cephalogram.jpg`
const pixels=computed(()=>points.value.length===2?Math.hypot(points.value[0]![0]-points.value[1]![0],points.value[0]![1]-points.value[1]![1]):null)
const millimetres=computed(()=>points.value.length===2?distanceMm(points.value[0]!,points.value[1]!,Number(calibration.value)):null)
const angle=computed(()=>points.value.length===3?angleDegrees(points.value[0]!,points.value[1]!,points.value[2]!):null)
async function openImage(url:string,label:string,isSample:boolean){
 const token=++generation;loading.value=true;error.value=''
 try{const image=new Image();image.src=url;await image.decode();if(token!==generation){if(url.startsWith('blob:'))URL.revokeObjectURL(url);return}if(image.naturalWidth*image.naturalHeight>40000000)throw new Error('Use an image of up to 40 megapixels.');
  let annotation:typeof experts.value=[]
  if(isSample){const r=await fetch(`${import.meta.env.BASE_URL}data/dental/reference-landmarks.json`);if(!r.ok)throw new Error('The expert annotations could not be loaded.');const data=await r.json();annotation=data.landmarks;if(!Array.isArray(annotation)||annotation.some(p=>!Number.isFinite(p.value?.x)||!Number.isFinite(p.value?.y)||p.value.x<0||p.value.y<0||p.value.x>image.naturalWidth||p.value.y>image.naturalHeight))throw new Error('The sample annotation does not fit this image.')}
  if(token!==generation)return;if(objectUrl&&objectUrl!==url)URL.revokeObjectURL(objectUrl);objectUrl=url.startsWith('blob:')?url:'';src.value=url;name.value=label;width.value=image.naturalWidth;height.value=image.naturalHeight;sample.value=isSample;experts.value=annotation;expertVisible.value=isSample;points.value=[];calibration.value=''
 }catch(e){if(url.startsWith('blob:'))URL.revokeObjectURL(url);if(token===generation)error.value=e instanceof Error?e.message:'Image could not be opened.'}finally{if(token===generation)loading.value=false}
}
function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;if(file.size>15000000||!/^image\/(png|jpeg|webp)$/.test(file.type)){error.value='Choose a PNG, JPEG or WebP image smaller than 15 MB. Export DICOM images to a de-identified image first.';return}void openImage(URL.createObjectURL(file),file.name,false)}
function place(event:MouseEvent){const svg=event.currentTarget as SVGSVGElement,ctm=svg.getScreenCTM();if(!ctm)return;const p=new DOMPoint(event.clientX,event.clientY).matrixTransform(ctm.inverse());if(p.x<0||p.y<0||p.x>width.value||p.y>height.value)return;if(points.value.length>=(tool.value==='length'?2:3))points.value=[];points.value.push([p.x,p.y])}
function coordinate(index:number,axis:0|1,event:Event){const value=Number((event.target as HTMLInputElement).value);if(!Number.isFinite(value))return;while(points.value.length<=index)points.value.push([0,0]);points.value[index]![axis]=Math.max(0,Math.min(axis===0?width.value:height.value,value))}
function exportPoints(){const blob=new Blob([JSON.stringify({schema_version:1,image:name.value,dimensions:[width.value,height.value],origin:'top-left',coordinates:'native-image-pixels',tool:tool.value,manual_points:points.value,mm_per_pixel:Number(calibration.value)>0?Number(calibration.value):null,measurement_mm:millimetres.value,angle_degrees:angle.value,expert_overlay:sample.value?'Aariz senior expert annotations; separate from manual points':null,diagnosis:null},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='dental-manual-landmarks.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
onBeforeUnmount(()=>{generation++;if(objectUrl)URL.revokeObjectURL(objectUrl)})
</script>
<template>
 <div class="dental-data-heading"><div><span class="dental-eyebrow">IMAGE REVIEW</span><h3>See the landmarks. Keep the evidence.</h3><p>Review an image and place measurement points manually.</p></div><div class="dental-file-actions"><button class="button-secondary" :disabled="loading" @click="openImage(referenceUrl,'Aariz · published validation reference',true)">Load reference X-ray</button><label class="button-primary dental-file-button"><AppIcon name="plus" :size="16"/>Open local image<input type="file" accept="image/png,image/jpeg,image/webp" @change="importFile"/></label></div></div>
 <p v-if="error" class="dental-error" role="alert">{{ error }}</p><p v-if="loading" role="status">Opening image…</p>
 <div v-if="src" class="dental-image-workbench"><div class="dental-radiograph-stage"><svg :viewBox="`0 0 ${width} ${height}`" role="img" :aria-label="`${name}. Use the point coordinate fields for keyboard measurement.`" @click="place"><image :href="src" :width="width" :height="height"/><g v-if="expertVisible" class="dental-expert-landmarks"><g v-for="p in experts" :key="p.symbol"><circle :cx="p.value.x" :cy="p.value.y" r="5"/><text :x="p.value.x+9" :y="p.value.y-5" font-size="18">{{ p.symbol }}</text></g></g><polyline v-if="points.length" :points="points.map(p=>p.join(',')).join(' ')" fill="none" stroke="#ffcc79" stroke-width="3"/><g v-for="(p,i) in points" :key="i"><circle :cx="p[0]" :cy="p[1]" r="7" fill="#ffcc79" stroke="#433725" stroke-width="2"/><text :x="p[0]+10" :y="p[1]+20" fill="#fff" font-size="20">{{ i+1 }}</text></g></svg><div class="dental-image-caption">{{ name }}<span>{{ width }} × {{ height }} px</span></div></div>
 <div class="dental-image-tools"><h4>Manual measurement</h4><p>Click {{ tool==='length'?'two':'three' }} points on the image, or enter pixel coordinates.</p><div class="dental-segmented"><button :aria-pressed="tool==='length'" @click="tool='length';points=[]">Distance</button><button :aria-pressed="tool==='angle'" @click="tool='angle';points=[]">Angle</button></div><div class="dental-point-fields" v-for="(_,i) in Array.from({length:tool==='length'?2:3})" :key="i"><span>Point {{ i+1 }}</span><label>X<input type="number" min="0" :max="width" :value="points[i]?.[0]??''" @change="coordinate(i,0,$event)"/></label><label>Y<input type="number" min="0" :max="height" :value="points[i]?.[1]??''" @change="coordinate(i,1,$event)"/></label></div><label v-if="tool==='length'" class="dental-field">Calibration · mm per pixel<input v-model="calibration" type="number" min="0.00001" step="0.00001" placeholder="From the image’s documented scale"/></label>
 <output class="dental-measurement-output" aria-live="polite">{{ tool==='angle'?(angle===null?'Place three distinct points':`${angle.toFixed(1)}°`):millimetres!==null?`${millimetres.toFixed(2)} mm`:pixels!==null?`${pixels.toFixed(1)} px`:'Place two points' }}<small>{{ tool==='length'&&millimetres===null?'A documented calibration is needed for millimetres.':'Manual geometric measurement; no clinical interpretation.' }}</small></output>
 <label v-if="sample" class="dental-check"><input v-model="expertVisible" type="checkbox"/>Show {{ experts.length }} expert landmarks</label><button class="button-secondary" @click="points=[]">Clear manual points</button><button class="button-primary" :disabled="!points.length" @click="exportPoints">Export manual points</button><p class="dental-small">The reference overlay comes from the dataset. Local images receive no automatic labels or diagnosis.</p></div></div>
 <div v-else class="dental-empty"><AppIcon name="scan" :size="42"/><h4>A closer look, with context.</h4><p>Open the published cephalogram or a de-identified local image. Images remain in this session.</p></div>
 <a class="dental-source-link" href="https://doi.org/10.6084/m9.figshare.27986417.v1" target="_blank" rel="noopener noreferrer">Aariz dataset · CC BY 4.0 · source and license ↗</a>
</template>
